from collections import defaultdict
class Solution(object):
    def minWindow(self, s, t):
        """
        :type s: str
        :type t: str
        :rtype: str
        """
        stack = []
        tail = 0

        tdict = defaultdict(int)
        for c in t:
            tdict[c]+=1
        sdict = defaultdict(int)
        for c in s:
            sdict[c]+=1

        for c in tdict:
            if c not in sdict or sdict[c]<tdict[c]:
                return ""

        minw = sys.maxint
        mins = ""
        count = len(tdict)
        for i,c in enumerate(s):
            if c in tdict:
                tdict[c]-=1
                if tdict[c]==0:
                    count-=1

                if count==0:
                    # advance the tail
                    for j in range(tail, i):
                        if s[j] in tdict:
                            if tdict[s[j]]==0:
                                tail = j
                                break
                            tdict[s[j]]+=1
                    w = i-tail+1
                    if w<minw:
                        minw = w
                        mins = s[tail:i+1]
        return mins

class Solution(object):
    def minWindow(self, s, t):
        """
        :type s: str
        :type t: str
        :rtype: str
        """
        from collections import Counter
        char_dict = Counter(t)
        min_len, min_start = float("inf"), 0
        l, r, cnt = 0, 0, len(t)
        while r < len(s):
            if s[r] in char_dict:
                if char_dict[s[r]] > 0:
                    cnt -= 1
                char_dict[s[r]] -= 1
            r += 1
            while cnt == 0:
                if min_len > r - l:
                    min_len = r - l
                    min_start = l
                if s[l] in char_dict:
                    char_dict[s[l]] += 1
                    if char_dict[s[l]] > 0:
                        cnt += 1
                l += 1
        if min_len == float("inf"):
            return ""
        return s[min_start: min_start + min_len]

